"""Controlled mock-only loading/retry/remount and real diagnostic export/backup UI."""
import json
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
root=Path(__file__).resolve().parents[1];out=root/'tests/visual/actual';out.mkdir(parents=True,exist_ok=True)
with sync_playwright() as p:
 b=p.chromium.launch()
 for width in [320,390,1280]:
  page=b.new_page(viewport={'width':width,'height':900});page.goto('http://127.0.0.1:5186');page.evaluate("""()=>{localStorage.clear();localStorage.setItem('wasteland-workshop-guided-tours',JSON.stringify({version:1,progress:{'intro-blueprints':{viewed:true,completed:false}}}));localStorage.setItem('wasteland-workshop-blueprint-collections',JSON.stringify([{id:'qa',name:'OCR Test',entries:[]} ]));localStorage.setItem('wasteland-workshop-active-blueprint-collection','qa')}""");page.reload()
  def nav(name):page.get_by_role('button',name='Open menu').click();page.get_by_role('button',name=name,exact=True).click()
  nav('Settings');toggle=page.get_by_label('Scan Diagnostics',exact=True);assert toggle.input_value()=='false';toggle.select_option('true');images=page.get_by_label('Include image data in diagnostic exports',exact=True);assert images.input_value()=='false';images.select_option('true');page.reload();nav('Settings');assert page.get_by_label('Scan Diagnostics',exact=True).input_value()=='true'
  with page.expect_download() as download:page.get_by_role('button',name='Export All Data',exact=True).click()
  backup=out/f'ocr-settings-backup-{width}.json';download.value.save_as(str(backup));data=json.loads(backup.read_text());assert data['data']['settings']['scanner']=={'diagnostics':True,'includeImages':True}
  page.evaluate("""async()=>{const {ocrService}=await import('/src/services/scanner/ScannerRuntime.ts');const {MockOcrProvider}=await import('/src/services/ocr/MockOcrProvider.ts');if(ocrService.state!=='NOT_LOADED')throw Error('Unexpected app-startup initialization');window.initCalls=0;window.scanCalls=0;window.cameraCalls=0;if(navigator.mediaDevices)navigator.mediaDevices.getUserMedia=()=>{window.cameraCalls++;throw Error('No camera expected')};ocrService.scanImage=()=>{window.scanCalls++;throw Error('No recognition expected')};await ocrService.replaceProvider(new MockOcrProvider(()=>{window.initCalls++;return new Promise(resolve=>{window.finishOcr=resolve})}))}""")
  nav('Scan Prints');loading=page.get_by_role('dialog',name='Loading OCR Library',exact=True);expect(loading).to_be_visible();expect(loading.get_by_text('Preparing the scanner...',exact=True)).to_be_visible();assert page.locator('.loading-dialog-spinner').count()==1;assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');page.screenshot(path=str(out/f'ocr-loading-{width}.png'));page.evaluate('window.finishOcr()');expect(loading).not_to_be_visible();assert page.evaluate('window.initCalls')==1
  nav('Blueprint Collections');nav('Scan Prints');assert loading.count()==0;assert page.evaluate('window.initCalls')==1
  with page.expect_file_chooser() as fc:page.get_by_role('button',name='Choose Image',exact=True).click()
  fc.value.set_files({'name':'camera-result.jpg','mimeType':'image/jpeg','buffer':b'not decoded'});expect(page.get_by_role('dialog',name='FILE SELECTED')).to_be_visible();page.get_by_role('button',name='OK',exact=True).click();page.get_by_text('Scan Diagnostics',exact=True).click()
  with page.expect_download() as download:page.get_by_role('button',name='Export Scan Diagnostics',exact=True).click()
  logs=out/f'ocr-events-{width}.json';download.value.save_as(str(logs));events=json.loads(logs.read_text());assert [e['type'] for e in events['records']]==['OCR_LOAD_STARTED','OCR_LOAD_SUCCEEDED','FILE_SELECTED'];assert events['records'][2]['text']=='camera-result.jpg';assert events['imageExportImplemented'] is False;assert page.evaluate('window.scanCalls===0&&window.cameraCalls===0')
  page.get_by_role('button',name='Clear Scan Diagnostics',exact=True).click()
  with page.expect_download() as download:page.get_by_role('button',name='Export Scan Diagnostics',exact=True).click()
  download.value.save_as(str(logs));assert json.loads(logs.read_text())['records']==[]
  nav('Blueprint Collections');page.evaluate("""async()=>{const {ocrService}=await import('/src/services/scanner/ScannerRuntime.ts');const {MockOcrProvider}=await import('/src/services/ocr/MockOcrProvider.ts');let attempt=0;await ocrService.replaceProvider(new MockOcrProvider(async()=>{attempt++;if(attempt===1)throw Error('Configured mock preparation failure')}))}""");nav('Scan Prints');failed=page.get_by_role('dialog',name='OCR INITIALIZATION FAILED',exact=True);expect(failed).to_be_visible();expect(failed.get_by_text('Configured mock preparation failure',exact=True)).to_be_visible();assert 'confirmation-dialog-danger' in failed.get_attribute('class');page.screenshot(path=str(out/f'ocr-load-failure-{width}.png'));failed.get_by_role('button',name='Retry',exact=True).click();expect(failed).not_to_be_visible();expect(page.get_by_role('button',name='Choose Image',exact=True)).to_be_visible()
  nav('Settings');page.get_by_label('Scan Diagnostics',exact=True).select_option('false');page.locator('#backup-file').set_input_files(str(backup));page.get_by_role('button',name='Replace & Restore',exact=True).click();page.wait_for_timeout(300);nav('Settings');assert page.get_by_label('Scan Diagnostics',exact=True).input_value()=='true'
  del data['data']['settings']['scanner'];old=out/f'old-settings-backup-{width}.json';old.write_text(json.dumps(data));page.locator('#backup-file').set_input_files(str(old));page.get_by_role('button',name='Replace & Restore',exact=True).click();page.wait_for_timeout(300);nav('Settings');assert page.get_by_label('Scan Diagnostics',exact=True).input_value()=='false'
  page.close()
 b.close()
print('Mock OCR loading/retry/remount, no recognition/camera, diagnostics clear/export and old/new backup restore passed on desktop/mobile.')
